def get_maxgold(gold, m, n):
    """Write a function to solve gold mine problem."""
    if m <= 0 or n <= 0:
        return 0
    if not gold or not gold[0]:
        return 0
    # dp[i][j] = max gold collectable starting from cell (i, j) to last column.
    dp = [[0] * n for _ in range(m)]
    for i in range(m):
        dp[i][n - 1] = gold[i][n - 1]
    for j in range(n - 2, -1, -1):
        for i in range(m):
            right = dp[i][j + 1]
            right_up = dp[i - 1][j + 1] if i > 0 else 0
            right_down = dp[i + 1][j + 1] if i + 1 < m else 0
            dp[i][j] = gold[i][j] + max(right, right_up, right_down)
    return max(dp[i][0] for i in range(m))
